// Current language (default: German)
let currentLanguage = localStorage.getItem('druckbau_language') || 'de';

// Translation function
function t(key) {
    return (window.translations && window.translations[currentLanguage] && window.translations[currentLanguage][key]) || key;
}

// Switch language
function switchLanguage(lang) {
    currentLanguage = lang;
    localStorage.setItem('druckbau_language', lang);
    updatePageLanguage();

    // Re-render dynamic components if they exist
    if (typeof window.renderProducts === 'function') window.renderProducts();
    if (typeof window.renderCart === 'function') window.renderCart();
    if (typeof window.renderWishlist === 'function') window.renderWishlist();
    if (typeof window.renderNews === 'function') window.renderNews();
}

// Update all translatable elements
function updatePageLanguage() {
    document.querySelectorAll('[data-i18n]').forEach(element => {
        const key = element.getAttribute('data-i18n');
        const translation = t(key);

        if (element.tagName === 'INPUT' || element.tagName === 'TEXTAREA') {
            element.placeholder = translation;
        } else {
            // Use innerHTML for elements with icons or complex structure
            if (element.querySelector('i, svg, span.arrow') || translation.includes('<')) {
                // If it's the "Warenkorb" header or similar, we might need more care.
                // For now, let's allow innerHTML if the key suggests it or if children exist.
                element.innerHTML = translation;
            } else {
                element.textContent = translation;
            }
        }
    });

    document.querySelectorAll('[data-i18n-alt]').forEach(element => {
        element.alt = t(element.getAttribute('data-i18n-alt'));
    });

    // Update HTML lang attribute
    document.documentElement.lang = currentLanguage;
}

function initTranslations() {
    if (typeof document === 'undefined') return;

    updatePageLanguage();
    document.querySelectorAll('.lang-btn').forEach(btn => {
        btn.classList.toggle('active', btn.getAttribute('data-lang') === currentLanguage);
        btn.addEventListener('click', () => {
            const lang = btn.getAttribute('data-lang');
            if (lang === 'de' || lang === 'en') switchLanguage(lang);
        });
    });
}

// --- js/utils.js ---
// js/utils.js

function formatCurrency(amount) {
    return new Intl.NumberFormat('de-DE', { style: 'currency', currency: 'EUR' }).format(amount);
}

function escapeHtml(unsafe) {
    if (!unsafe) return '';
    return unsafe
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#039;");
}

function showNotification(message, type = 'info', title = '') {
    const container = document.getElementById('toast-container');
    if (!container) {
        console.error('Toast container not found');
        return;
    }

    const toast = document.createElement('div');
    toast.className = `toast toast-${type}`;
    
    let icon = 'ℹ️';
    if (type === 'success') icon = '✅';
    if (type === 'error') icon = '❌';
    if (type === 'warning') icon = '⚠️';

    if (!title) {
        if (type === 'success') title = 'Erfolg';
        else if (type === 'error') title = 'Fehler';
        else if (type === 'warning') title = 'Warnung';
        else title = 'Info';
    }

    toast.innerHTML = `
        <div class="toast-icon">${icon}</div>
        <div class="toast-content">
            <div class="toast-title">${title}</div>
            <div class="toast-message">${message}</div>
        </div>
        <button class="toast-close">&times;</button>
    `;

    container.appendChild(toast);

    const closeBtn = toast.querySelector('.toast-close');
    closeBtn.onclick = () => {
        toast.classList.add('toast-out');
        setTimeout(() => toast.remove(), 300);
    };

    setTimeout(() => {
        if (toast.parentElement) {
            toast.classList.add('toast-out');
            setTimeout(() => toast.remove(), 300);
        }
    }, 5000);
}

function showSuccess(msg, title = 'Erfolg') { showNotification(msg, 'success', title); }
function showError(msg, title = 'Fehler') { showNotification(msg, 'error', title); }
function showWarning(msg, title = 'Warnung') { showNotification(msg, 'warning', title); }
function showInfo(msg, title = 'Info') { showNotification(msg, 'info', title); }

function setError(input, message) {
    if (!input) return;
    input.classList.add('error');
    input.classList.remove('success');
    input.setAttribute('aria-invalid', 'true');
    const errorSpan = input.closest('.custom-field')?.querySelector('.form-error')
        || input.parentElement.querySelector('.form-error');
    if (errorSpan) errorSpan.textContent = message;
}

function setSuccess(input) {
    if (!input) return;
    input.classList.remove('error');
    input.classList.add('success');
    input.removeAttribute('aria-invalid');
    const errorSpan = input.closest('.custom-field')?.querySelector('.form-error')
        || input.parentElement.querySelector('.form-error');
    if (errorSpan) errorSpan.textContent = '';
}

